mapper.select:
SELECT TRUNC(statistics_time) AS date, COALESCE(ROUND(SUM(ec_duration),2),0) AS energySavingHour, COALESCE(ROUND(SUM(ec_kwh),2),0) AS energySavedKwh FROM bbx_device_ec_statistics WHERE statistics_time >= TRUNC(SYSDATE) - 30
AND tenant_id = #{tenantId}
GROUP BY TRUNC(statistics_time) ORDER BY date

SELECT r.id AS roomId, r.room_name AS roomName, COALESCE(ROUND(SUM(ec_kwh),2),0) AS energySavedKwh FROM bbx_meeting_room r LEFT JOIN bbx_meeting_room_device_rel rel ON r.id = rel.room_id LEFT JOIN bbx_device_ec_statistics s ON rel.device_id = s.device_id WHERE r.deleted = 1
AND r.tenant_id = #{tenantId}
GROUP BY r.id,r.room_name ORDER BY energySavedKwh ${sortOrder}
